def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances = {}
    frozen = set()
    history = []
    rejected = []

    for i, op in enumerate(ops):
        parts = op.split(' ')
        verb = parts[0]

        success = False
        action = None

        if verb == 'open':
            if len(parts) == 3:
                acc, amt_str = parts[1], parts[2]
                # Validate amount is non-empty and consists only of digits 0-9
                if amt_str and all('0' <= c <= '9' for c in amt_str):
                    amt = int(amt_str)
                    # N >= 0 is guaranteed by digit check, but keeping for clarity
                    if amt >= 0 and acc not in balances:
                        balances[acc] = amt
                        action = ('open', acc, amt)
                        success = True
        elif verb == 'deposit':
            if len(parts) == 3:
                acc, amt_str = parts[1], parts[2]
                if amt_str and all('0' <= c <= '9' for c in amt_str):
                    amt = int(amt_str)
                    if amt > 0 and acc in balances:
                        balances[acc] += amt
                        action = ('deposit', acc, amt)
                        success = True
        elif verb == 'withdraw':
            if len(parts) == 3:
                acc, amt_str = parts[1], parts[2]
                if amt_str and all('0' <= c <= '9' for c in amt_str):
                    amt = int(amt_str)
                    if amt > 0 and acc in balances and acc not in frozen and balances[acc] >= amt:
                        balances[acc] -= amt
                        action = ('withdraw', acc, amt)
                        success = True
        elif verb == 'transfer':
            if len(parts) == 4:
                src, dst, amt_str = parts[1], parts[2], parts[3]
                if amt_str and all('0' <= c <= '9' for c in amt_str):
                    amt = int(amt_str)
                    if amt > 0 and src != dst and src in balances and dst in balances and src not in frozen and balances[src] >= amt:
                        balances[src] -= amt
                        balances[dst] += amt
                        action = ('transfer', src, dst, amt)
                        success = True
        elif verb == 'freeze':
            if len(parts) == 2:
                acc = parts[1]
                if acc in balances and acc not in frozen:
                    frozen.add(acc)
                    action = ('freeze', acc)
                    success = True
        elif verb == 'unfreeze':
            if len(parts) == 2:
                acc = parts[1]
                if acc in balances and acc in frozen:
                    frozen.remove(acc)
                    action = ('unfreeze', acc)
                    success = True
        elif verb == 'undo':
            if len(parts) == 1:
                if history:
                    last = history.pop()
                    op_type = last[0]
                    if op_type == 'open':
                        _, acc, _ = last
                        if acc in balances:
                            del balances[acc]
                    elif op_type == 'deposit':
                        _, acc, amt = last
                        balances[acc] -= amt
                    elif op_type == 'withdraw':
                        _, acc, amt = last
                        balances[acc] += amt
                    elif op_type == 'transfer':
                        _, src, dst, amt = last
                        balances[src] += amt
                        balances[dst] -= amt
                    elif op_type == 'freeze':
                        _, acc = last
                        frozen.discard(acc)
                    elif op_type == 'unfreeze':
                        _, acc = last
                        frozen.add(acc)
                    success = True

        if not success:
            rejected.append(i)
        else:
            if action is not None:
                history.append(action)

    return balances, rejected
